-- Ditto SDK 5.2.0 (every SDK)
--
-- Document ID generation
--
-- Offline devices cannot coordinate a sequence. Generate collision-free IDs
-- on the device: UUID v4 (primary recommendation), a time-ordered random ID
-- such as ULID, a composite object, a natural key, or an ID generated by
-- Ditto (omit _id). Do not depend on the format of generated IDs.
--
-- Allowed _id values: strings (recommended), objects (composite keys),
-- integers/booleans/arrays (accepted, not recommended). Floats and null are
-- rejected.
--
-- How to generate a UUID v4 and a fixed-precision UTC timestamp in each SDK:
-- "IDs and Timestamps in <SDK>" on your SDK's page.
--
-- Guide: § Document IDs

-- ---------------------------------------------------------------------------
-- ✅ GOOD: Collision-free IDs
-- ---------------------------------------------------------------------------

-- ✅ GOOD: UUID v4. Independent devices never need to coordinate.
-- Arguments: {"order": {"_id": "3f0c9a8e-5b1d-4c2a-9e7f-1a2b3c4d5e6f", "storeId": "store-12", "status": "open", "createdAt": "2026-10-08T10:30:00.123Z"}}
INSERT INTO orders DOCUMENTS (:order)

-- ✅ GOOD: Natural key. The SKU is globally unique and immutable, so two
-- devices that create the same product intentionally end up with one
-- document whose fields merge.
-- Arguments: {"product": {"_id": "SKU-48213", "name": "Paper cups", "priceCents": 450}}
INSERT INTO products DOCUMENTS (:product) ON ID CONFLICT DO UPDATE_LOCAL_DIFF

-- ✅ GOOD: Let Ditto generate the ID when nothing else needs to know it
-- before the insert, and read it back from the result's mutated document IDs.
-- Arguments: {"note": {"text": "Call the supplier", "createdAt": "2026-10-08T10:30:00.123Z"}}
INSERT INTO notes DOCUMENTS (:note)

-- ---------------------------------------------------------------------------
-- ❌ BAD: Sequential and timestamp-only IDs
-- ---------------------------------------------------------------------------

-- ❌ BAD: "order-42" built from a daily count collides when two offline
-- devices create the 42nd order of the day. After sync the two documents
-- become one, with fields from both orders mixed together.
-- Arguments: {"order": {"_id": "order-42", "status": "open"}}
INSERT INTO orders DOCUMENTS (:order)

-- ❌ BAD: An ID built from the current epoch milliseconds collides when two
-- devices write within the same millisecond, and device clocks are not
-- reliable anyway.
-- Arguments: {"order": {"_id": "order-1759919400123", "status": "open"}}
INSERT INTO orders DOCUMENTS (:order)

-- ---------------------------------------------------------------------------
-- ✅ GOOD: Human-readable display numbers, separate from _id
-- ---------------------------------------------------------------------------

-- A display label, not an identifier: uniqueness is not guaranteed across
-- devices, so never use it as _id or as a lookup key. A stable terminal code
-- that you assign, plus a local sequence padded to four digits ("T3-0042"),
-- avoids most duplicates; show the date alongside it.
-- Arguments: {"order": {"_id": "3f0c9a8e-5b1d-4c2a-9e7f-1a2b3c4d5e6f", "displayNumber": "T3-0042", "createdAt": "2026-10-08T10:30:00.123Z"}}
INSERT INTO orders DOCUMENTS (:order)
